cl.sql:
SELECT GSoffered
FROM schools
WHERE ABS(Longitude) = (
    SELECT MAX(ABS(Longitude))
    FROM schools
);

SELECT country
FROM circuits
WHERE alt = (
    SELECT MAX(alt)
    FROM circuits
);

SELECT wins
FROM driverStandings
WHERE points = 91;

SELECT MAX(Symptoms)
FROM Examination
WHERE Diagnosis = 'SLE';

SELECT Segment
FROM customers
WHERE CustomerID = (
    SELECT MIN(CustomerID)
    FROM customers
);
